**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int sumaDzielnikow(int n) {
    int suma = 0;
    for (int i = 1; i <= n / 2; i++) {
        if (n % i == 0) suma += i;
    }
    return suma;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    int dosk = 0, nadm = 0, nied = 0;
    while (plik >> n) {
        int s = sumaDzielnikow(n);
        cout << n << ": suma dzielnikow = " << s << " -> ";
        if (s == n) { cout << "doskonala" << endl; dosk++; }
        else if (s > n) { cout << "nadmiarowa" << endl; nadm++; }
        else { cout << "niedostateczna" << endl; nied++; }
    }
    cout << "Doskonale: " << dosk << ", nadmiarowe: " << nadm << ", niedostateczne: " << nied << endl;
    return 0;
}
```

**Wyjasnienie**: Dzielniki wlasciwe to dzielniki < n. Wystarczy iterowac do n/2 (wiekszy dzielnik wlasciwy niz n/2 nie istnieje). Liczby doskonale sa bardzo rzadkie (6, 28, 496, 8128...).

